#include <bits/stdc++.h>
using namespace std;

pair<int, int> pos[10];
vector<pair<int, int>> moves;

bool valid(int x, int y) {
    return (x >= 0 && x < 3 && y >= 0 && y < 3) || (x == 3 && y == 1);
}

bool test(int x, int y) {
    if (!valid(x, y)) return false;

    for (const auto& move : moves) {
        x += move.first;
        y += move.second;
        if (!valid(x, y)) return false;
    }

    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            pos[i * 3 + j + 1] = {i, j};

    pos[0] = {3, 1};

    for (int i = 0; i + 1 < n; ++i) {
        int x = s[i] - '0';
        int y = s[i + 1] - '0';
        moves.push_back({
            pos[y].first - pos[x].first,
            pos[y].second - pos[x].second
        });
    }

    int counter = 0;

    for (int i = 0; i <= 9; ++i)
        if (test(pos[i].first, pos[i].second))
            ++counter;

    cout << (counter == 1 ? "YES" : "NO");

    return 0;
}

